import React, { useState, useEffect } from 'react';
import Papa from 'papaparse'; // Ensure you have this installed: npm install papaparse
import './RiverDashboard.css';

// ==========================================
// CONFIGURATION
// ==========================================

// 1. BACKEND CONNECTION
// Set this to your Django backend URL (e.g., http://localhost:8000 or your production IP)
const BACKEND_API_URL = 'http://localhost:8000'; 

// 2. AWS S3 CONFIGURATION
const USE_S3 = true;       // Set to true to fetch from AWS
const S3_PUBLIC = false;   // Set to false to use your Django 's3_presign' view (Recommended for security)
const S3_BUCKET = 'aqi-training'; // Used only if S3_PUBLIC is true
const S3_REGION = 'us-east-1';    // Used only if S3_PUBLIC is true

// 3. FILE NAMES
const CSV_FILE_NAME = 'forecast_outputs.csv';
const TXT_FILE_NAME = 'lime_short_sentences.txt';

const RiverDashboard = () => {
    const [chartData, setChartData] = useState([]);
    const [limeSentences, setLimeSentences] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [lastUpdated, setLastUpdated] = useState(null);

    // ==========================================
    // HELPER: Get the Download URL
    // ==========================================
    const getFileUrl = async (fileName) => {
        // Option A: Local Files
        if (!USE_S3) return `./${fileName}`;

        // Option B: Public S3 Bucket (Direct Link)
        if (S3_PUBLIC) {
            return `https://${S3_BUCKET}.s3.${S3_REGION}.amazonaws.com/${fileName}`;
        }

        // Option C: Private S3 Bucket (via Django s3_presign)
        // We call the view from your views.py: def s3_presign(request)
        try {
            const response = await fetch(`${BACKEND_API_URL}/api/s3-presign?file=${fileName}`);
            if (!response.ok) throw new Error('Failed to get S3 URL from backend');
            const data = await response.json();
            return data.url; // This is the temporary signed URL from AWS
        } catch (err) {
            console.error("Error fetching presigned URL:", err);
            return null;
        }
    };

    // ==========================================
    // DATA FETCHING LOGIC
    // ==========================================
    const fetchData = async () => {
        setLoading(true);
        setError(null);

        try {
            // 1. Get the URLs for both files
            // We use 'await' to ensure we have the valid signed URLs before trying to download
            const csvUrl = await getFileUrl(CSV_FILE_NAME);
            const txtUrl = await getFileUrl(TXT_FILE_NAME);

            if (!csvUrl || !txtUrl) throw new Error("Could not generate file URLs.");

            // 2. Prepare Cache Busting
            // We append a timestamp (?t=...) to force the browser to ignore its cache and get the new hourly file.
            // Note: Presigned URLs already have query params, so we check if we need '&' or '?'
            const cacheBuster = (url) => {
                const separator = url.includes('?') ? '&' : '?';
                return `${url}${separator}t=${new Date().getTime()}`;
            };

            // 3. Fetch CSV Data
            // We fetch the text first, then parse it. This is more robust for S3 than passing the URL directly to Papa.
            const csvResponse = await fetch(cacheBuster(csvUrl));
            const csvText = await csvResponse.text();
            
            Papa.parse(csvText, {
                header: true,
                skipEmptyLines: true,
                complete: (results) => {
                    const parsedData = results.data.map(row => ({
                        time: row.Timestamp, // Adjust based on your CSV header
                        level: parseFloat(row.Predicted_Water_Level)
                    }));
                    setChartData(parsedData);
                },
                error: (err) => {
                    throw new Error(`CSV Parse Error: ${err.message}`);
                }
            });

            // 4. Fetch LIME Sentences (Text File)
            const txtResponse = await fetch(cacheBuster(txtUrl));
            const txtData = await txtResponse.text();
            // Split by newlines and filter empty lines
            const lines = txtData.split('\n').filter(line => line.trim() !== '');
            setLimeSentences(lines);

            setLastUpdated(new Date().toLocaleTimeString());
            setLoading(false);

        } catch (err) {
            console.error("Error fetching data:", err);
            setError("Failed to load real-time data. Please try again.");
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
        // Optional: Auto-refresh every 10 minutes (600000ms) to check for hourly updates
        const interval = setInterval(fetchData, 600000); 
        return () => clearInterval(interval);
    }, []);

    // ==========================================
    // RENDER
    // ==========================================
    return (
        <div className="dashboard-container">
            <h1 className="dashboard-title">River Water Level Forecast</h1>
            
            {/* Status Bar */}
            <div style={{ textAlign: 'center', marginBottom: '20px', color: '#666' }}>
                {loading && <span>⏳ Fetching latest S3 data...</span>}
                {error && <span style={{color: 'red'}}>❌ {error}</span>}
                {!loading && !error && <span>✅ Live Data (Updated: {lastUpdated})</span>}
            </div>

            <div className="dashboard-content">
                
                {/* Chart Section */}
                <div className="chart-card">
                    <h2>Water Level Trends</h2>
                    {/* Placeholder for your Chart Component */}
                    {chartData.length > 0 ? (
                        <div style={{padding: '20px', background: '#f8f9fa', borderRadius: '8px'}}>
                            {/* Pass 'chartData' to your Recharts/Chart.js component here */}
                             <p>Chart loaded with {chartData.length} data points.</p>
                             <p>Latest Prediction: {chartData[0]?.level} meters</p>
                        </div>
                    ) : (
                        <p>No chart data available.</p>
                    )}
                </div>

                {/* LIME Explanations Section */}
                <div className="lime-card">
                    <h2>AI Explanations</h2>
                    <div className="lime-list">
                        {limeSentences.map((line, index) => {
                             // Simple logic to color code based on keywords in your text file
                             const isGreen = line.includes('increase') || line.includes('high'); // adjust logic as needed
                             const icon = 'ℹ️'; 
                             
                             return (
                                 <div key={index} className="lime-item">
                                     <div className="lime-icon">{icon}</div>
                                     <div style={{fontWeight: 500}}>{line}</div>
                                 </div>
                             )
                        })}
                    </div>
                </div>

                {/* Disclaimer */}
                <div style={{ marginTop: '30px', background: 'white', borderRadius: '15px', padding: '25px', boxShadow: '0 10px 25px rgba(0,0,0,0.1)' }}>
                    <div style={{ padding: '15px', background: '#fff3cd', borderRadius: '10px', color: '#856404', textAlign: 'center', fontSize: '0.9em' }}>
                        <strong>DISCLAIMER:</strong> This system provides general flood risk information. 
                        In emergency, call 100 (Police) or 101 (Fire & Rescue).
                    </div>
                </div>

            </div>

            {/* Floating Refresh Button */}
            <button className="refresh-btn" onClick={fetchData} title="Refresh Data">
                🔄
            </button>
        </div>
    );
};

export default RiverDashboard;
